//! What `lf-mide clean` can free, and doing it.
//!
//! The plan only looks: it measures and proposes, never changes anything.
//! Deleting goes through [`crate::guard`], one item at a time.

use std::path::{Path, PathBuf};

use lf_mide_core::{ProcessKind, format_size};
use lf_mide_system::System;

use crate::categories;
use crate::guard::{self, Roots};

/// How safe a category is to clean.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Safety {
    /// Regenerated by the next build. Chosen by default with `--delete`.
    Rebuildable,
    /// Safe, but has a cost (a slow next start, interrupted work): only
    /// with `--include`.
    Careful,
}

/// What cleaning a category does.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Action {
    /// Delete each item (under its base folder).
    Delete,
    /// Run one command that does the whole job.
    Command { program: String, args: Vec<String> },
    /// Ask these processes to end.
    StopProcesses(Vec<(u32, ProcessKind)>),
    /// Nothing is done for you: the advice says how.
    ReportOnly,
}

/// One thing in a category.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Item {
    pub label: String,
    /// What to delete, for [`Action::Delete`].
    pub path: Option<PathBuf>,
    /// The folder `path` must lie strictly inside.
    pub base: Option<PathBuf>,
    pub bytes: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Category {
    pub id: &'static str,
    pub title: String,
    pub why: String,
    pub safety: Safety,
    pub action: Action,
    pub items: Vec<Item>,
    /// Commands or notes for the user (the whole point of report-only ones).
    pub advice: Vec<String>,
    /// Why it cannot be done right now (for example an app is running).
    pub blocked: Option<String>,
}

impl Category {
    pub fn bytes(&self) -> u64 {
        self.items
            .iter()
            .fold(0u64, |sum, i| sum.saturating_add(i.bytes))
    }

    pub fn is_actionable(&self) -> bool {
        self.action != Action::ReportOnly && !self.items.is_empty() && self.blocked.is_none()
    }
}

/// Everything that decides where to look.
#[derive(Debug, Clone)]
pub struct CleanEnv {
    pub home: PathBuf,
    /// Gradle's user home (`~/.gradle`, or `GRADLE_USER_HOME`).
    pub gradle_home: PathBuf,
    /// The project root, when run inside one.
    pub project: Option<PathBuf>,
    pub own_pid: u32,
    /// Unix seconds, for "older than a week".
    pub now_secs: i64,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Plan {
    pub categories: Vec<Category>,
}

/// Looks at the machine and proposes what could be cleaned. Changes nothing.
pub fn plan(sys: &dyn System, env: &CleanEnv) -> Plan {
    Plan {
        categories: categories::all(sys, env),
    }
}

/// The ids chosen by default, plus `include` (careful ones), limited to
/// `only` when given.
pub fn selection(plan: &Plan, include: &[String], only: &[String]) -> Vec<&'static str> {
    plan.categories
        .iter()
        .filter(|c| c.is_actionable())
        .filter(|c| c.safety == Safety::Rebuildable || include.iter().any(|id| id == c.id))
        .filter(|c| only.is_empty() || only.iter().any(|id| id == c.id))
        .map(|c| c.id)
        .collect()
}

/// Ids that are not categories at all (a typo should not silently do
/// nothing). A real category with nothing to clean today is not unknown.
pub fn unknown_ids(ids: &[String]) -> Vec<&str> {
    ids.iter()
        .map(String::as_str)
        .filter(|id| !categories::IDS.contains(id))
        .collect()
}

/// What happened to one item.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Outcome {
    pub category: &'static str,
    pub label: String,
    /// Bytes freed, or why not.
    pub result: Result<u64, String>,
}

/// The folders deleting may touch: the home folder and the project.
pub fn roots_for(env: &CleanEnv) -> Roots {
    let mut allowed: Vec<&Path> = vec![env.home.as_path(), env.gradle_home.as_path()];
    if let Some(project) = &env.project {
        allowed.push(project.as_path());
    }
    Roots::new(&allowed)
}

/// Cleans the categories in `ids`.
pub fn execute(plan: &Plan, ids: &[&str], sys: &dyn System, env: &CleanEnv) -> Vec<Outcome> {
    let roots = roots_for(env);
    let mut outcomes = Vec::new();
    for category in plan.categories.iter().filter(|c| ids.contains(&c.id)) {
        if !category.is_actionable() {
            continue;
        }
        // The plan may be minutes old (a question waits for an answer): look
        // again at what is running before touching anything an app uses.
        if let Some(reason) = categories::blocked_now(sys, env, category) {
            outcomes.push(Outcome {
                category: category.id,
                label: category.title.clone(),
                result: Err(format!("not done: {reason}")),
            });
            continue;
        }
        match &category.action {
            Action::Delete => outcomes.extend(delete_items(category, &roots)),
            Action::Command { program, args } => {
                outcomes.push(run_command(category, program, args, sys));
            }
            Action::StopProcesses(targets) => {
                outcomes.extend(stop_processes(category, targets, sys, env.own_pid));
            }
            Action::ReportOnly => {}
        }
    }
    outcomes
}

fn delete_items(category: &Category, roots: &Roots) -> Vec<Outcome> {
    category
        .items
        .iter()
        .map(|item| {
            let result = match (&item.path, &item.base) {
                (Some(path), Some(base)) => guard::delete(path, base, roots)
                    .map(|()| item.bytes)
                    .map_err(|refusal| refusal.text()),
                _ => Err("nothing to delete here".to_string()),
            };
            Outcome {
                category: category.id,
                label: item.label.clone(),
                result,
            }
        })
        .collect()
}

fn run_command(category: &Category, program: &str, args: &[String], sys: &dyn System) -> Outcome {
    let args: Vec<&str> = args.iter().map(String::as_str).collect();
    let result = match sys.run(program, &args) {
        Ok(out) if out.success => Ok(category.bytes()),
        Ok(out) => Err(first_line(&out.text())),
        Err(error) => Err(error.to_string()),
    };
    Outcome {
        category: category.id,
        label: format!("{program} {}", args.join(" ")),
        result,
    }
}

fn first_line(text: &str) -> String {
    text.lines()
        .find(|l| !l.trim().is_empty())
        .unwrap_or("the command failed")
        .trim()
        .to_string()
}

fn stop_processes(
    category: &Category,
    targets: &[(u32, ProcessKind)],
    sys: &dyn System,
    own_pid: u32,
) -> Vec<Outcome> {
    targets
        .iter()
        .map(|(pid, kind)| {
            let label = format!("{} (pid {pid})", kind.label());
            let bytes = category
                .items
                .iter()
                .find(|i| i.label == label)
                .map_or(0, |i| i.bytes);
            // The list is a few seconds old: only signal what is still the
            // same kind of process.
            let result = if *pid <= 1 || *pid == own_pid || i32::try_from(*pid).is_err() {
                Err("refused".to_string())
            } else if !lf_mide_perf::is_still(sys, *pid, *kind, own_pid) {
                Err("no longer running".to_string())
            } else {
                // SAFETY: a plain signal to a process just confirmed to be
                // the one listed; the pid is positive and fits a pid_t.
                let sent = unsafe { libc::kill(*pid as libc::pid_t, libc::SIGTERM) };
                if sent == 0 {
                    Ok(bytes)
                } else {
                    Err(std::io::Error::last_os_error().to_string())
                }
            };
            Outcome {
                category: category.id,
                label,
                result,
            }
        })
        .collect()
}

/// `1.8G`-style total for display.
pub fn total_text(bytes: u64) -> String {
    format_size(bytes)
}
